<?php $page_title='Settings';require 'includes/header.php';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$a=$_POST['action']??'';if($a==='store'){foreach(['store_email','store_phone','store_address','currency','tax_rate','shipping_cost','low_stock_threshold'] as $k=>$v){$pdo->prepare("INSERT INTO site_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)")->execute([$k,trim($_POST[$v]??'')]);}flash('success','Store settings saved.');}if($a==='profile'){if(!empty($_POST['password']))$pdo->prepare("UPDATE users SET name=?,email=?,password=? WHERE id=?")->execute([trim($_POST['name']),trim($_POST['email']),password_hash($_POST['password'],PASSWORD_DEFAULT),$_SESSION['user_id']]);else$pdo->prepare("UPDATE users SET name=?,email=? WHERE id=?")->execute([trim($_POST['name']),trim($_POST['email']),$_SESSION['user_id']]);flash('success','Admin profile updated.');}header('Location: settings.php');exit;}$settings=[];foreach($pdo->query("SELECT setting_key,setting_value FROM site_settings") as $r)$settings[$r['setting_key']]=$r['setting_value'];?>
<div class="page-head"><div><h1>Settings</h1><p>Store configuration and admin profile.</p></div></div><div class="grid-2"><div class="panel"><h2>Admin Profile</h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="profile"><div class="field"><label>Name</label><input class="input" name="name" value="<?=e($admin['name'])?>" required></div><div class="field"><label>Email</label><input class="input" type="email" name="email" value="<?=e($admin['email'])?>" required></div><div class="field"><label>New password (optional)</label><input class="input" type="password" name="password" minlength="8"></div><button class="btn">Save profile</button></form></div><div class="panel"><h2>Store Settings</h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="store"><?php foreach(['store_email'=>'Email','store_phone'=>'Phone','store_address'=>'Address','currency'=>'Currency','tax_rate'=>'Tax Rate %','shipping_cost'=>'Shipping Cost','low_stock_threshold'=>'Low Stock Threshold'] as $k=>$label):?><div class="field"><label><?=$label?></label><input class="input" name="<?=$k?>" value="<?=e($settings[$k]??'')?>"></div><?php endforeach;?><button class="btn">Save store settings</button></form></div></div><?php require 'includes/footer.php';?>
